class Solution {
public:
    int minCost(int maxTime, vector<vector<int>>& edges, vector<int>& passingFees) {
        int n = passingFees.size();
        vector<vector<pair<int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> minTime(n, INT_MAX);
        priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<>> pq;
        pq.push({passingFees[0], 0, 0});
        minTime[0] = 0;

        while (!pq.empty()) {
            auto [cost, u, t] = pq.top();
            pq.pop();
            if (u == n - 1) return cost;
            for (auto& [v, travelTime] : adj[u]) {
                int nt = t + travelTime;
                if (nt <= maxTime && nt < minTime[v]) {
                    minTime[v] = nt;
                    pq.push({cost + passingFees[v], v, nt});
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        java.util.List<int[]>[] adj = new java.util.ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        int[] minTime = new int[n];
        java.util.Arrays.fill(minTime, Integer.MAX_VALUE);
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{passingFees[0], 0, 0});
        minTime[0] = 0;

        while (!pq.isEmpty()) {
            int[] curr = pq.poll();
            int cost = curr[0], u = curr[1], t = curr[2];
            if (u == n - 1) return cost;
            for (int[] edge : adj[u]) {
                int v = edge[0], travelTime = edge[1];
                int nt = t + travelTime;
                if (nt <= maxTime && nt < minTime[v]) {
                    minTime[v] = nt;
                    pq.offer(new int[]{cost + passingFees[v], v, nt});
                }
            }
        }
        return -1;
    }
}

var minCost = function(maxTime, edges, passingFees) {
  const n = passingFees.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v, time] of edges) {
    adj[u].push([v, time]);
    adj[v].push([u, time]);
  }
  const minTime = new Array(n).fill(Infinity);
  // Simple min-heap simulation or array sort
  const q = [[passingFees[0], 0, 0]];
  minTime[0] = 0;

  while (q.length > 0) {
    q.sort((a, b) => a[0] - b[0]);
    const [cost, u, t] = q.shift();
    if (u === n - 1) return cost;
    for (const [v, travelTime] of adj[u]) {
      const nt = t + travelTime;
      if (nt <= maxTime && nt < minTime[v]) {
        minTime[v] = nt;
        q.push([cost + passingFees[v], v, nt]);
      }
    }
  }
  return -1;
